export function setupBenchLighting122(view,key){view.key122=key;key.position.set(-3,5,5);key.target.position.set(.35,1.1,0);view.scene.add(key.target);key.shadow.camera.left=-4.4;key.shadow.camera.right=4.4;key.shadow.camera.top=3.8;key.shadow.camera.bottom=-3.8;key.shadow.camera.near=.2;key.shadow.camera.far=18;key.shadow.camera.updateProjectionMatrix();key.shadow.bias=-.00006;key.shadow.normalBias=.002;key.shadow.radius=2;key.castShadow=true;view.renderer.shadowMap.type=THREE.PCFSoftShadowMap;view.scene.traverse(o=>{if(o.isMesh)o.receiveShadow=true;});updateBenchLighting122(view);}
export function benchShadows122(root){let count=0;root.traverse(o=>{if(!o.isMesh)return;const mats=Array.isArray(o.material)?o.material:[o.material];o.receiveShadow=true;o.castShadow=!mats.some(m=>m.transparent||m.isMeshBasicMaterial)&&count++<220;});return count;}
export function updateBenchLighting122(view){if(!view.key122||!view.renderer.shadowMap)return;const pref=visualState105(),enable=pref.quality!=='performance'&&!view.budget?.reduced,size=pref.quality==='cinematic'?2048:1024;if(view.shadowKey122===enable+':'+size)return;view.shadowKey122=enable+':'+size;view.renderer.shadowMap.enabled=enable;view.key122.castShadow=enable;if(view.key122.shadow.mapSize.x!==size){view.key122.shadow.map?.dispose();view.key122.shadow.map=null;view.key122.shadow.mapSize.set(size,size);}view.renderer.shadowMap.needsUpdate=true;}
export function inspectionGround122(scene){const group=new THREE.Group();group.name='Sol_inspection122';const floor=new THREE.Mesh(new THREE.CircleGeometry(65,64),new THREE.MeshStandardMaterial({name:'Piso concreto inspeccion122',color:'#354044',roughness:.83}));floor.rotation.x=-Math.PI/2;floor.position.y=-.035;floor.receiveShadow=true;floor.raycast=()=>{};group.add(floor);const shadow=contactShadow105(17.5,3.5);shadow.position.y=-.02;group.add(shadow);group.userData.shadow122=shadow;scene.add(group);return group;}
